function scenarioInner(){const d=scenarioData();return `<div class="scenario-top"><div class="inline"><div class="window-dots"><span></span><span></span><span></span></div><span class="small-label">${tr('Pregled kreditnog portfolija','Loan portfolio review')}</span></div>${tag(tr('SINTETIČKI PODACI','SYNTHETIC DATA'),'warm')}</div><div class="scenario-toolbar" role="group" aria-label="${tr('Faza ilustracije','Illustration stage')}">${[tr('1 · Priprema','1 · Prepared'),tr('2 · Zaustavljanje','2 · Stopped'),tr('3 · Novo izvršenje','3 · New run')].map((s,i)=>`<button data-action="scenario" data-value="${i}" aria-pressed="${scenario===i}">${s}</button>`).join('')}<button class="play-btn" data-action="play" aria-label="${tr(playing?'Pauziraj ilustraciju':'Pokreni ilustraciju',playing?'Pause illustration':'Play illustration')}" title="${tr(playing?'Pauziraj':'Pokreni animaciju',playing?'Pause':'Play animation')}">${icon(playing?'pause':'play')}</button></div><div class="scenario-inner"><div class="scenario-status"><h3>${d.title}</h3>${tag(d.badge,d.kind)}</div><div class="metrics3"><div class="metric"><div class="metric-value">${d.total}</div><label>${tr('očekivanih računa','expected accounts')}</label></div><div class="metric"><div class="metric-value ${scenario===1?'red':scenario===2?'accent':'warm'}">${d.missing}</div><label>${tr('nedostaje u pregledu','missing from report')}</label></div><div class="metric"><div class="metric-value ${scenario===0?'warm':'accent'}">${d.ready}</div><label>${tr('računa u pregledu','accounts in report')}</label></div></div><div class="quality-track" aria-hidden="true"><span style="width:${scenario===0?'0':scenario===1?'98.8':'100'}%"></span></div><div class="scenario-lines">${[tr('Obrada podataka','Data processing'),tr('Obavezna provera','Required check'),tr('Naredni korak toka','Next workflow step')].map((l,i)=>`<div class="scenario-line"><span>${l}</span><span class="outcome ${d.states[i]}">${icon(d.states[i]==='ok'?'checkcircle':d.states[i]==='fail'?'stop':'clock')}${d.lines[i]}</span></div>`).join('')}</div><div class="scenario-history">${icon('history')}<span>${d.history}</span></div></div>`;}
function scenarioAside(){const d=scenarioData();return `<div class="story-copy"><span class="small-label">${tr('Isti proces · tri poslovna pogleda','One process · three business views')}</span><h3>${d.head}</h3><p>${d.desc}</p></div><div class="role-list">${[tr('Uprava','Leadership'),tr('Rukovodilac','Process manager'),tr('Operativni tim','Operations team')].map((r,i)=>`<div class="role-item">${icon(['chart','users','search'][i])}<div><strong>${r}</strong><p>${d.roles[i]}</p></div></div>`).join('')}</div><div class="case-mini-links">${smallLink(tr('Bankarski primer','Banking example'),'case','bank')}${smallLink(tr('Lanac snabdevanja','Supply chain'),'case','supply')}</div>`;}
function slide4(){return head(tr('04 / Od tehničkog uspeha do prihvatljivog rezultata','04 / From technical success to an accepted result'),tr('Obrada je završena.<br><em>Da li rezultat sme dalje?</em>','Processing is complete.<br><em>Is the result ready to proceed?</em>'),tr('Jedna obavezna provera povezuje podatke, ishod procesa i sledeći dozvoljeni korak.','One required check connects the data, process outcome and next permitted step.'))+`<div class="scenario-layout"><div class="scenario-panel" id="scenarioPanel">${scenarioInner()}</div><div class="scenario-aside" id="scenarioAside">${scenarioAside()}</div></div><div class="meta-line"><span>${tr('Ilustrativni scenario; nije ekran aplikacije ni živo izvršenje. Zaustavljanje važi za definisani tok. Automatska ispravka nije prikazana niti obećana.','Illustrative scenario; not an application screenshot or a live execution. The stop applies to the configured flow. Automatic repair is neither shown nor promised.')}</span>${source('04 · 06')}</div>`;}
function slide5(){return head(tr('05 / Proizvod i ekspertiza imaju različite uloge','05 / Product and expertise play different roles'),tr('Platforma daje osnovu.<br><em>Partner oblikuje rešenje.</em>','The platform provides the foundation.<br><em>The partner shapes the solution.</em>'),tr('Postojeći sistemi ostaju izvor poslovnih evidencija. Zajednički rad usmerava se na konkretan proces klijenta.','Existing systems remain the source of business records. The shared effort focuses on a specific customer process.'))+`<div class="grid3"><div class="card responsibility-card"><div class="small-label">${tr('Sistemi klijenta','Customer systems')}</div><h3>${tr('Izvorne evidencije<br>i transakcije','Original records<br>and transactions')}</h3><p>${tr('Poslovni sistemi nastavljaju da vode podatke i operacije za koje su namenjeni.','Business systems continue to own the records and operations they were designed for.')}</p>${checkItems([tr('Izvorne evidencije i odgovorni vlasnici','Source records and accountable owners'),tr('Postojeći procesi i aplikacije','Existing processes and applications'),tr('Vlasnici podataka i odgovornosti','Data owners and accountabilities')])}</div><div class="card responsibility-card featured"><div class="small-label">${tr('Proizvod / advanexus','Product / advanexus')}</div><h3>${tr('Povezano<br>izvršavanje i provera','Connected<br>execution and checks')}</h3><p>${tr('Podržani izvori, obrada, provere, pregledi i evidencija objedinjeni su u platformi.','Supported sources, processing, checks, views and evidence are brought together in the platform.')}</p>${checkItems([tr('Ponovljivi tokovi rada','Repeatable workflows'),tr('Vidljivi ishodi i odstupanja','Visible outcomes and exceptions'),tr('Dostupni kontekst i evidencija','Available context and evidence')])}</div><div class="card responsibility-card"><div class="small-label">${tr('Partner / stručna isporuka','Partner / expert delivery')}</div><h3>${tr('Domensko znanje<br>i uspešna primena','Domain expertise<br>and successful adoption')}</h3><p>${tr('Poznavanje klijenta pretvara mogućnosti platforme u pravila, tokove i prihvaćen rezultat.','Knowledge of the customer turns platform capabilities into rules, workflows and an accepted result.')}</p>${checkItems([tr('Analiza procesa i poslovna pravila','Process analysis and business rules'),tr('Povezivanje i prilagođavanje','Integration and adaptation'),tr('Obuka, primopredaja i podrška','Training, handover and support')])}</div></div><p class="main-takeaway">${tr('Zajedničke sposobnosti već postoje u proizvodu.<br><em>Stručni rad usmerava se na proces klijenta.</em>','Shared capabilities are already part of the product.<br><em>Expert work focuses on the customer’s process.</em>')}</p><div class="meta-line"><span>${tr('Podela je okvir za dogovor; obim integracije i odgovornosti potvrđuju se za konkretan angažman.','This is a basis for agreement; integration scope and responsibilities are confirmed for each engagement.')}</span>${source('01 · 02')}</div>`;}
